/**
 * SLATE — earrings and chains, real, and a hundred of each for each side.
 *
 * Jewelry used to hang on one peg, so a chain and a pair of earrings could
 * not be worn at once. They have their own pegs now, and this is what goes on
 * them: four hundred products, a hundred men's earrings, a hundred women's, a
 * hundred men's necklaces and chains, a hundred women's.
 *
 * A note on who wears what. Most of this is genuinely worn by everybody, and
 * a great deal of the fine jewelry here is sold from the same case to the
 * same people whatever the house's marketing says. The split below follows
 * how the houses themselves merchandise the pieces — a Cuban link at fifteen
 * millimetres sits in the men's case, a pearl drop in the women's — and it
 * changes nothing about what the game will let you buy or wear. Nothing here
 * is refused to anybody.
 *
 * Brands and product lines are public record. Prices, quality figures and
 * how well a piece holds its value are SLATE's own calibration, and say so.
 */

import type { Money } from '../core/money';
import { REFERENCE_VERSION } from './reference';
import type { RealGood } from './goods';

const REAL = {
  source: 'calibrated_estimate', confidence: 'high', version: REFERENCE_VERSION,
  note: 'Brand and piece are public record. Price and how it holds value are SLATE’s calibration.',
} as const;

const ALL_YEAR = ['Spring', 'Summer', 'Autumn', 'Winter'];

/** A pair of earrings, or a single. */
const er = (
  id: string, name: string, brand: string, sub: string, price: Money,
  audience: 'men' | 'women' | 'unisex', quality: number, depreciation = 0.12,
): RealGood => ({
  id, name, type: 'product', category: 'jewelry', subcategory: sub, basePrice: price, brand,
  tags: ['jewellery', 'earrings', sub], quality, depreciation, slot: 'earrings',
  formality: 58, seasons: ALL_YEAR, audience, ...REAL,
});

/** Something worn round the neck. */
const nk = (
  id: string, name: string, brand: string, sub: string, price: Money,
  audience: 'men' | 'women' | 'unisex', quality: number, formality = 58, depreciation = 0.12,
): RealGood => ({
  id, name, type: 'product', category: 'jewelry', subcategory: sub, basePrice: price, brand,
  tags: ['jewellery', 'necklace', sub], quality, depreciation, slot: 'necklace',
  formality, seasons: ALL_YEAR, audience, ...REAL,
});

